head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30692";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30692.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_name", fn: function () { return String((dma_pageContext.get("name") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_search();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30692.btn_search_onclick' }); }
};

/**
 * @method
 * @name grd_List_2_oncellclick
 * @description grd_List_2 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_List');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_List */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: choice (인자 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_List_2.oncellclick' });
    }
};

/**
 * @method
 * @name img_56_onclick
 * @description img_56 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_56_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30692.img_56_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_search = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — PersonInfo.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — PersonInfo.do", unresolved: "action:PersonInfo.do" };
};

/**
 * @method
 * @name setFormatDate
 * @description set Format Date 처리
 * @param {*} date date
 * @returns {void}
 * @hidden N
 */
scwin.setFormatDate = function (date) {
    return date.substring(0, 4) + "-" + date.substring(4, 6) + "-" + date.substring(6, 8);
};

/**
 * @method
 * @name choice
 * @description choice 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.choice = function (obj) {
    const value = obj.value.split(",");
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).form).comCode.value = value[0];
    $c.util.getComponent("ipt_name").setValue(value[1]);
    if (((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).form).birthday != null) {
        ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).form).birthday.value = value[2];
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const f = (document.form || { elements: [] });
    f.action = "PersonInfo.do";
    $c.util.getComponent("ipt_name").setValue(encodeURI($c.util.getComponent('ipt_name').getValue()));
    await scwin.tx_search();
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
